import React from "react";
import { useNavigate } from "react-router-dom";

function HomePage({ availableSlots, setAvailableSlots }) {
  const navigate = useNavigate();

  const handleBookNow = () => {
    if (availableSlots > 0) {
      navigate("/booking");
    } else {
      alert("No slots available!");
    }
  };

  return (
    <div style={styles.page}>
      {/* Navbar */}
      <div style={styles.navbar}>
        <h2 style={{ margin: 0 }}>🚗 Parking Slot System</h2>
        <div style={styles.navRight}>Welcome, User</div>
      </div>

      <div style={styles.mainContent}>
        {/* Sidebar */}
        <div style={styles.sidebar}>
          <h3 style={styles.sidebarTitle}>Menu</h3>
          <button style={styles.sidebarBtn} onClick={() => navigate("/")}>
            Home
          </button>
          <button style={styles.sidebarBtn} onClick={() => navigate("/profile")}>
  Profile
</button>

          <button style={styles.sidebarBtn} onClick={() => navigate("/about")}>
            About
          </button>
          <button style={styles.sidebarBtn} onClick={() => navigate("/settings")}>
            Settings
          </button>
          <hr style={{ margin: "10px 0" }} />
          <button style={styles.sidebarBtn} onClick={() => navigate("/booking")}>
            Booking
          </button>
          <button style={styles.sidebarBtn} onClick={() => navigate("/payment")}>
            Payment
          </button>
          <button style={styles.sidebarBtn} onClick={() => navigate("/success")}>
            Success
          </button>
        </div>

        {/* Content Area */}
        <div style={styles.content}>
          <h1>Parking Slot Dashboard</h1>
          <h2>Available Slots: {availableSlots}</h2>
          <button style={styles.button} onClick={handleBookNow}>
            Book Now
          </button>
        </div>
      </div>
    </div>
  );
}

const styles = {
  page: { display: "flex", flexDirection: "column", height: "100vh" },
  navbar: {
    background: "#333",
    color: "#fff",
    padding: "15px 20px",
    fontSize: "20px",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center"
  },
  navRight: { fontSize: "16px" },
  mainContent: { display: "flex", flex: 1 },
  sidebar: {
    width: "220px",
    background: "#f4f4f4",
    padding: "20px",
    display: "flex",
    flexDirection: "column",
    gap: "8px"
  },
  sidebarTitle: { marginBottom: "10px", fontSize: "18px" },
  sidebarBtn: {
    padding: "10px",
    border: "none",
    background: "#ddd",
    cursor: "pointer",
    fontSize: "16px",
    textAlign: "left",
    borderRadius: "4px"
  },
  content: { flex: 1, padding: "20px", textAlign: "center" },
  button: {
    padding: "10px 20px",
    fontSize: "18px",
    cursor: "pointer",
    background: "#007bff",
    color: "#fff",
    border: "none",
    borderRadius: "4px"
  }
};

export default HomePage;
